-- Requirement count checks shown after a successful clean load.
SELECT 'organizers' AS requirement_name, COUNT(*) AS actual_count, 5 AS minimum_count FROM Organizer;
SELECT 'customers' AS requirement_name, COUNT(*) AS actual_count, 100 AS minimum_count FROM Customer;
SELECT 'venues' AS requirement_name, COUNT(*) AS actual_count, 8 AS minimum_count FROM Venue;
SELECT 'events' AS requirement_name, COUNT(*) AS actual_count, 20 AS minimum_count FROM Event;
SELECT 'performances' AS requirement_name, COUNT(*) AS actual_count, 60 AS minimum_count FROM Performance;
SELECT 'purchase_orders' AS requirement_name, COUNT(*) AS actual_count, 300 AS minimum_count FROM Transactions WHERE transaction_type = 'purchase';
SELECT 'tickets' AS requirement_name, COUNT(*) AS actual_count, 800 AS minimum_count FROM Tickets;
SELECT 'ticket_cancellations' AS requirement_name, COUNT(*) AS actual_count, 1 AS minimum_count FROM TicketCancellation;
SELECT 'resale_listings' AS requirement_name, COUNT(*) AS actual_count, 1 AS minimum_count FROM ResaleListing;
SELECT 'reviewed_events' AS requirement_name, COUNT(DISTINCT p.event_id) AS actual_count, 10 AS minimum_count FROM Reviews r JOIN Performance p ON p.performance_id = r.performance_id;
